import json
Ch = [[-1] * 4]; Itm = [-1]
def digits(a):
    return [(a // 4 ** k) % 4 for k in range(5)]
def walk(a, grow):
    v = 0
    for g in digits(a):
        if Ch[v][g] < 0:
            if not grow:
                return -1
            Ch.append([-1] * 4); Itm.append(-1); Ch[v][g] = len(Ch) - 1
        v = Ch[v][g]
    return v
for a, b in [(6, 40), (22, 41), (7, 42)]:
    Itm[walk(a, True)] = b
print(json.dumps({"digits22": digits(22), "nodes": len(Ch), "get22": Itm[walk(22, False)], "get6": Itm[walk(6, False)]}))
